package com.example.onlineshop.catalog.persistence;
import com.example.onlineshop.catalog.application.*;import com.example.onlineshop.catalog.domain.*;import java.sql.*;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;
@Repository public class PostgresProductRepository implements CatalogProductRepository {
 private static final String PROJECTION="SELECT p.id,p.name,p.description,s.price_amount,s.currency,s.available_quantity,p.created_at,p.updated_at FROM product p JOIN product_sku s ON s.product_id=p.id AND s.is_default";private final JdbcTemplate jdbc;public PostgresProductRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Override @Transactional public CatalogProduct save(CatalogProduct p){p.defaultSku();p.validateInvariants();Timestamp created=Timestamp.from(p.createdAt()),updated=Timestamp.from(p.updatedAt());boolean exists=jdbc.queryForObject("SELECT count(*) FROM product WHERE id=?",Integer.class,p.id())>0;if(!exists)jdbc.update("INSERT INTO product (id,legacy_id,slug,name,description,status,created_at,created_by,updated_at,updated_by,version) VALUES (?,?,?,?,?,?,?,?,?,?,?)",p.id(),p.legacyId(),p.slug(),p.name(),p.description(),p.status().name(),created,p.createdBy(),updated,p.updatedBy(),p.version());else if(jdbc.update("UPDATE product SET slug=?,name=?,description=?,status=?,updated_at=?,updated_by=?,version=? WHERE id=? AND version=?",p.slug(),p.name(),p.description(),p.status().name(),updated,p.updatedBy(),p.version(),p.id(),p.version()-1)!=1)throw new OptimisticConflictException();
  for(ProductSku sku:p.skus()){Integer count=jdbc.queryForObject("SELECT count(*) FROM product_sku WHERE id=?",Integer.class,sku.id());if(count==0)jdbc.update("INSERT INTO product_sku (id,product_id,sku,status,price_amount,currency,available_quantity,is_default,variant_signature,created_at,created_by,updated_at,updated_by,version) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",sku.id(),p.id(),sku.sku(),sku.status().name(),sku.price(),sku.currency(),sku.availableQuantity(),sku.defaultSku(),sku.variantSignature(),created,p.createdBy(),updated,p.updatedBy(),sku.version());else{Long dbVersion=jdbc.queryForObject("SELECT version FROM product_sku WHERE id=? AND product_id=?",Long.class,sku.id(),p.id());if(sku.version()<dbVersion||sku.version()>dbVersion+1)throw new OptimisticConflictException();int n=jdbc.update("UPDATE product_sku SET status=?,price_amount=?,available_quantity=?,is_default=?,variant_signature=?,updated_at=?,updated_by=?,version=? WHERE id=? AND product_id=? AND version=?",sku.status().name(),sku.price(),sku.availableQuantity(),sku.defaultSku(),sku.variantSignature(),updated,p.updatedBy(),sku.version(),sku.id(),p.id(),dbVersion);if(n!=1)throw new OptimisticConflictException();}jdbc.update("DELETE FROM product_sku_attribute_value WHERE product_sku_id=?",sku.id());sku.attributes().forEach((attributeId,value)->jdbc.update("INSERT INTO product_sku_attribute_value(product_sku_id,attribute_id,value_id) VALUES (?,?,?)",sku.id(),attributeId,value.id()));}
  jdbc.update("DELETE FROM product_attribute_assignment WHERE product_id=?",p.id());p.attributes().forEach((attributeId,values)->values.forEach(value->jdbc.update("INSERT INTO product_attribute_assignment(product_id,attribute_id,value_id) VALUES (?,?,?)",p.id(),attributeId,value.id())));jdbc.update("DELETE FROM product_category WHERE product_id=?",p.id());p.categoryIds().forEach(categoryId->jdbc.update("INSERT INTO product_category(product_id,category_id) VALUES (?,?)",p.id(),categoryId));return p;}
 @Override public Optional<CatalogProduct> findAggregate(UUID id){
  var products=jdbc.query("SELECT * FROM product WHERE id=?",(r,n)->new CatalogProduct(r.getObject("id",UUID.class),r.getObject("legacy_id",UUID.class),r.getString("slug"),r.getString("name"),r.getString("description"),LifecycleStatus.valueOf(r.getString("status")),r.getObject("created_by",UUID.class),r.getObject("updated_by",UUID.class),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant(),r.getLong("version")),id);if(products.isEmpty())return Optional.empty();var p=products.get(0);
  jdbc.query("SELECT * FROM product_sku WHERE product_id=? ORDER BY id",(r,n)->{var sku=new ProductSku(r.getObject("id",UUID.class),r.getString("sku"),LifecycleStatus.valueOf(r.getString("status")),r.getBigDecimal("price_amount"),r.getString("currency").trim(),r.getInt("available_quantity"),r.getBoolean("is_default"),r.getLong("version"));jdbc.query("SELECT a.*,v.id value_id,v.attribute_data_type,v.text_value,v.integer_value,v.decimal_value,v.boolean_value,v.display_value FROM product_sku_attribute_value x JOIN product_attribute a ON a.id=x.attribute_id JOIN product_attribute_value v ON v.id=x.value_id WHERE x.product_sku_id=?",(ar,i)->{sku.restoreAssignment(attribute(ar),value(ar));return null;},sku.id());p.restoreSku(sku);return null;},id);
  jdbc.query("SELECT a.*,v.id value_id,v.attribute_data_type,v.text_value,v.integer_value,v.decimal_value,v.boolean_value,v.display_value FROM product_attribute_assignment x JOIN product_attribute a ON a.id=x.attribute_id JOIN product_attribute_value v ON v.id=x.value_id WHERE x.product_id=?",(r,n)->{p.restoreAssignment(attribute(r),value(r));return null;},id);
  jdbc.query("SELECT category_id FROM product_category WHERE product_id=?",(r,n)->{p.restoreCategory(r.getObject(1,UUID.class));return null;},id);return Optional.of(p);
 }
 private ProductAttribute attribute(ResultSet r)throws SQLException{return new ProductAttribute(r.getObject("id",UUID.class),r.getString("code"),r.getString("name"),AttributeDataType.valueOf(r.getString("data_type")),AttributeScope.valueOf(r.getString("scope")),r.getBoolean("is_variant_axis"),r.getBoolean("is_filterable"),r.getBoolean("is_required"),r.getString("validation_json"),r.getInt("display_order"),LifecycleStatus.valueOf(r.getString("status")));}
 private AttributeValue value(ResultSet r)throws SQLException{var type=AttributeDataType.valueOf(r.getString("attribute_data_type"));Object data=switch(type){case TEXT->r.getString("text_value");case INTEGER->r.getLong("integer_value");case DECIMAL->r.getBigDecimal("decimal_value");case BOOLEAN->r.getBoolean("boolean_value");};return new AttributeValue(r.getObject("value_id",UUID.class),r.getObject("id",UUID.class),type,data,r.getString("display_value"));}
 @Override @Transactional public ProductAttribute save(ProductAttribute a,UUID actor,Instant now){Timestamp t=Timestamp.from(now);jdbc.update("INSERT INTO product_attribute (id,code,name,data_type,scope,is_variant_axis,is_filterable,is_required,validation_json,status,display_order,created_at,created_by,updated_at,updated_by) VALUES (?,?,?,?,?,?,?,?,?::jsonb,?,?,?,?,?,?)",a.id(),a.code(),a.name(),a.dataType().name(),a.scope().name(),a.variantAxis(),a.filterable(),a.required(),a.validationJson(),a.status().name(),a.displayOrder(),t,actor,t,actor);for(AttributeValue v:a.values()){Object text=null,integer=null,decimal=null,bool=null;switch(v.dataType()){case TEXT->text=v.value();case INTEGER->integer=v.value();case DECIMAL->decimal=v.value();case BOOLEAN->bool=v.value();}jdbc.update("INSERT INTO product_attribute_value (id,attribute_id,attribute_data_type,text_value,integer_value,decimal_value,boolean_value,display_value,created_at,created_by,updated_at,updated_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",v.id(),v.attributeId(),v.dataType().name(),text,integer,decimal,bool,v.displayValue(),t,actor,t,actor);}return a;}
 @Override public Category save(Category c,UUID actor,Instant now){Timestamp t=Timestamp.from(now);jdbc.update("INSERT INTO category (id,slug,name,description,parent_id,status,display_order,created_at,created_by,updated_at,updated_by,version) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",c.id(),c.slug(),c.name(),c.description(),c.parentId(),c.status().name(),c.displayOrder(),t,actor,t,actor,c.version());return c;}@Override public ProductImage save(ProductImage i,UUID actor,Instant now){Timestamp t=Timestamp.from(now);jdbc.update("INSERT INTO product_image (id,product_id,product_sku_id,url,alt_text,display_order,is_primary,created_at,created_by,updated_at,updated_by,version) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",i.id(),i.productId(),i.skuId(),i.url(),i.altText(),i.displayOrder(),i.primary(),t,actor,t,actor,i.version());return i;}
 @Override public Optional<Product> findV1(UUID id){return jdbc.query(PROJECTION+" WHERE p.id=?",this::map,id).stream().findFirst();}@Override public ProductRepository.Page findV1Page(int page,int size){long total=jdbc.queryForObject("SELECT count(*) FROM product p WHERE EXISTS (SELECT 1 FROM product_sku s WHERE s.product_id=p.id AND s.is_default)",Long.class);var content=jdbc.query(PROJECTION+" ORDER BY p.created_at DESC,p.id DESC LIMIT ? OFFSET ?",this::map,size,(long)page*size);return new ProductRepository.Page(content,total);}private Product map(ResultSet r,int row)throws SQLException{return new Product(r.getObject("id",UUID.class),r.getString("name"),r.getString("description"),r.getBigDecimal("price_amount"),r.getString("currency").trim(),r.getInt("available_quantity"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());}
}
